        $token=bin2hex(random_bytes(32));$now=new DateTimeImmutable();$payload=['presetMetrics'=>$compiled['metrics'],'datasetPreview'=>$dataset,'effectiveScenes'=>$compiled['effectiveScenes'],'defaultVersion'=>$compiled['defaultVersion'],'controlRequest'=>['mode'=>'preset','presetKey'=>$presetKey]];Db::connect('partner')->table('partner_control_preview')->insert(['token_hash'=>hash('sha256',$token),'actor_id'=>(int)$actor['id'],'channel_id'=>$channelId,'game_id'=>$gameId,'currency_code'=>$currency,'preset_key'=>$presetKey,'expected_version'=>$expectedVersion,'payload_json'=>json_encode($payload,JSON_THROW_ON_ERROR|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),'expires_at'=>$now->add(new DateInterval('PT10M'))->format('Y-m-d H:i:s'),'used_at'=>null,'created_at'=>$now->format('Y-m-d H:i:s')]);$this->audit->record('game_control.preview','success',$ip,$agent,(int)$actor['id'],(int)$actor['channel_id'],(string)$actor['role_code'],'control_profile',$channelId.':'.$gameId,'',null,null,['currencyCode'=>$currency,'presetKey'=>$presetKey,'expectedVersion'=>$expectedVersion]);return ['previewToken'=>$token,'expiresAt'=>$now->add(new DateInterval('PT10M'))->format(DATE_ATOM),'channelId'=>$channelId,'gameId'=>$gameId,'currencyCode'=>$currency,'presetKey'=>$presetKey,'expectedVersion'=>$expectedVersion,'metrics'=>$dataset['metrics'],'presetMetrics'=>$compiled['metrics'],'affectsAllCurrencies'=>true];
