        try{$newVersion=$db->transaction(function($gameDb)use($channel,$game,$expectedVersion,$profile,$actor,$ip,$reason){$locked=$gameDb->table('s_slot_control_profile')->where(['channel_id'=>$channel,'game_id'=>$game])->lock(true)->find();if(!is_array($locked)||(int)$locked['version']!==$expectedVersion)throw new RuntimeException('CONTROL_VERSION_CONFLICT');$version=$expectedVersion+1;$gameDb->table('s_slot_control_profile')->where(['channel_id'=>$channel,'game_id'=>$game])->update(['version'=>$version,'status'=>0,'load_status'=>'pending','load_error'=>'','updated_by'=>(int)$actor['id']]);$gameDb->table('d_slot_control_revision')->insert(['channel_id'=>$channel,'game_id'=>$game,'version'=>$version,'parent_version'=>(int)$profile['parent_version'],'preset_key'=>(string)$profile['preset_key'],'action'=>'reset','source_json'=>json_encode(['restoreDefault'=>true],JSON_THROW_ON_ERROR),'effective_scenes_json'=>$profile['effective_scenes_json'],'validation_json'=>json_encode(['ok'=>true,'reason'=>trim($reason)],JSON_THROW_ON_ERROR|JSON_UNESCAPED_UNICODE),'operator_id'=>(int)$actor['id'],'operator_name'=>(string)$actor['display_name'],'operator_ip'=>$ip]);return $version;});}catch(\Throwable $e){$partner->table('partner_idempotency_request')->where(['action'=>'game_control.restore_default','idempotency_key'=>$idempotencyKey])->update(['status'=>'failed','response_json'=>json_encode(['error'=>$e->getMessage()]),'updated_at'=>$now]);throw $e;}
